public int maximizingXor(int l, int r) {
    int best = 0;
    for (int a = l; a <= r; a++) {
        for (int b = a; b <= r; b++) {   // b starts at a so a == b is allowed
            best = Math.max(best, a ^ b);
        }
    }
    return best;
}

code.python:
def maximizingXor(l: int, r: int) -> int:
    best = 0
    for a in range(l, r + 1):
        for b in range(a, r + 1):        # b starts at a so a == b is allowed
            best = max(best, a ^ b)
    return best

