code.java:
public int maximizingXor(int l, int r) {
    int d = l ^ r;
    if (d == 0) return 0;                     // l == r → only pair is (l, l)
    int p = 31 - Integer.numberOfLeadingZeros(d);  // index of top set bit
    return (1 << (p + 1)) - 1;                // all ones in bits 0..p
}

code.python:
def maximizingXor(l: int, r: int) -> int:
    d = l ^ r
    if d == 0:                                # l == r → only pair is (l, l)
        return 0
    p = d.bit_length() - 1                     # index of top set bit
    return (1 << (p + 1)) - 1                  # all ones in bits 0..p

